#include <iomanip>
#include <iostream>
#include <vector>

int main()
{
    int n{};
    std::cin >> n;

    std::vector<int> scores{};
    for (int i{ 0 }; i < n; ++i)
    {
        int score{};
        std::cin >> score;
        scores.push_back(score);
    }

    if (scores.empty())
    {
        std::cout << "No scores\n";
        return 0;
    }

    int highest{ scores[0] };
    int lowest{ scores[0] };
    int total{ 0 };
    for (int score : scores)
    {
        if (score > highest) highest = score;
        if (score < lowest) lowest = score;
        total += score;
    }

    std::cout << "Scores: " << scores.size() << '\n';
    std::cout << "Highest: " << highest << '\n';
    std::cout << "Lowest: " << lowest << '\n';
    std::cout << "Average: " << std::fixed << std::setprecision(1) << static_cast<double>(total) / static_cast<double>(scores.size()) << '\n';
    return 0;
}
